import { FACTIONS, RESOURCES } from './data.js';
import { blocOf, hegemonyProgress, joinIssue, peaceTerms, activeWar } from './power.js';
import { systemKnown } from './intelligence.js';
import { systemsOf } from './world.js';
import { getPlanet } from './state.js';
import { realmName } from './space-news.js';
import { esc,fmt,button } from './ui-format.js';

export function powerPanel(state) {
 const p=hegemonyProgress(state,'player'),h=state.galaxy.hegemony,b=blocOf(state,'player');
 return `<div class="detail-card"><div class="card-heading"><strong>Vorherrschaft im Sektor</strong><span class="status-badge">${fmt(p.share*100)} % / 66,7 %</span></div><div class="progress"><span style="width:${Math.min(100,p.share*150)}%"></span></div><p>Beherrsche zwei Drittel des festen Systemgewichts für 120 aufeinanderfolgende Tage.</p><p class="note">${h.leader===p.leader?`${h.streak} / 120 Tage gehalten`:'Haltephase noch nicht begonnen'} · ${p.healthy?'Führung finanziert und versorgt':'Führung benötigt eine gedeckte Kasse, mindestens 30 Zufriedenheit und tägliche Nahrung auf jeder eigenen Welt'}.</p><details class="management-fold" data-panel-detail="hegemony-rules"><summary>Kontrolle und Siegbedingungen</summary><p class="note">Ein System zählt vollständig, sobald deine Führung und verbindliche Mitglieder mindestens 55 % seiner ursprünglichen planetaren Bedeutung halten. Unbesiedelte Welten müssen erschlossen werden. Kleine Außenposten unter 40 Einwohnern zählen noch nicht. Leere Sterne und Orbitalruinen zählen nicht; Zerstörung verringert die notwendige Gesamtleistung nicht. KI-Reiche können ebenfalls gewinnen.</p></details></div><details class="management-fold" data-panel-detail="hegemony-systems"><summary class="section-title">Kartierte Systeme</summary>${p.systems.filter(s=>systemKnown(state,s.id)).map(s=>`<div class="stat-line"><span>${esc(systemsOf(state).find(t=>t.id===s.id).name)}</span><strong>${!s.weight?'Kein Siedlungsraum':s.controlled?'Kontrolle gesichert':'Kontrolle offen'}</strong></div>`).join('')}<p class="note">Unkartierte Systeme erscheinen nach Erkundung. Politische Blockadressen offenbaren keine Bevölkerung, Lager oder militärische Stärke.</p></details><div class="section-title">Dein Machtblock</div>${b?`<div class="detail-card"><strong>${esc(b.name)}</strong><p>Führung: ${esc(realmName(state,b.leader))}<br>Mitglieder: ${b.members.map(id=>esc(realmName(state,id))).join(' · ')||'Noch keine'}</p><p class="note">+6 % Forschung und Zugang zu Blockhäfen gegen örtliche Versorgungspreise. Mitglied: 2 ¢ Beitrag pro Tag. Führung: 4 ¢ Betrieb je Mitglied, davon bis zu 2 ¢ durch Beiträge gedeckt. Drei verfehlte Monatsbeiträge oder Versorgungszusagen führen zum Austritt; erneuter Beitritt nach 180 Tagen.</p>${b.leader==='player'?`${b.members.map(id=>{const t=b.terms[id],r=t.request;return `<div class="detail-card"><strong>${esc(realmName(state,id))}</strong><p class="note">Vertragsbrüche: ${t.misses} / 3${r?` · ${fmt(r.delivered)} / ${r.amount} ${RESOURCES[r.resource].name} bis Tag ${r.until} nach ${esc(getPlanet(state,r.planet).name)}`:' · kein offenes Versorgungsersuchen'}</p>${r&&r.delivered<r.amount?button('Versorgung mit freiem Frachter senden','bloc-supply',`data-member="${id}"`):''}</div>`;}).join('')}<p class="note">Versorgungen laden echte Waren am eigenen Hafen und buchen Reiseenergie. Verlorene oder verspätete Frachter erfüllen keine Zusage.</p>${button(b.autoSupply?'Automatische Versorgung ausschalten':'Automatische Versorgung einschalten','bloc-auto','',!state.tech.includes('smartLogistics'))}${!state.tech.includes('smartLogistics')?'<p class="research-condition unmet">Automatik benötigt Smarte Versorgungsrouten.</p>':''}`:''}${button(b.leader==='player'?'Machtbund auflösen':'Machtbund verlassen','bloc-leave')}</div>`:`<p class="note">Du bist unabhängig. Gründe ab zwei Kolonien mit Vertragsdiplomatie, Kommunikationszentrale und Diplomatischem Forum einen Machtbund.</p>${button('Machtbund gründen · 250 ¢','bloc-create')}`}${b?.leader==='player'?`<div class="section-title">Mitgliedschaft anbieten</div>${Object.keys(state.relations).filter(id=>!joinIssue(state,'player',id)).map(id=>button(`${esc(FACTIONS[id].name)} einladen`,'bloc-invite',`data-faction="${id}"`)).join('')||'<p class="note">Aktuell fehlen geeignete Partner. Handel und mindestens 55 Beziehungen bilden die Grundlage; beide Seiten müssen die Verpflichtungen finanzieren können.</p>'}`:''}<details class="management-fold" data-panel-detail="other-blocs"><summary class="section-title">Öffentliche Machtblöcke</summary>${state.galaxy.blocs.filter(q=>q!==b).map(q=>`<p class="note"><strong>${esc(q.name)}</strong><br>${q.members.map(id=>esc(realmName(state,id))).join(' · ')||'Noch keine Mitglieder'}</p>`).join('')||'<p class="note">Noch keine weiteren Machtblöcke.</p>'}</details>`;
}
export function warMarkup(state,id) {
 const w=activeWar(state,'player',id),terms=peaceTerms(state,'player',id);
 const claim=w?.target&&getPlanet(state,w.target);
 return `<p class="note">${claim?`Erklärter Anspruch: ${esc(claim.name)} · ${esc(realmName(state,w.attacker))}.`:'Begrenzter Konflikt ohne einzelnen planetaren Anspruch.'}<br>${esc(terms.reason)}</p>${button(terms.accepted?`Frieden vereinbaren · ${terms.cost} ¢`:'Friedensbedingungen noch nicht erfüllt','diplomacy',`data-faction="${id}" data-kind="peace"`,!terms.accepted)}`;
}
